def shell(file,title,body,wide=False):
    field_names={'source-kind':'資料の種類','source-status':'原本の結果','feature-group':'業務で絞り込み','netlify-plan':'Netlify','resend-plan':'通知メール','github-seats':'GitHub Teamの開発者数','ai-budget':'AI予算（USD／月）','domain-budget':'ドメイン予算（円／年）','fx':'換算レート（円／USD）'}
    for id,label in field_names.items():
        body=body.replace(f'id="{id}"',f'id="{id}" aria-label="{label}"')
    nav=''.join(f'<a href="{p}"'+(' aria-current="page"' if p==file else '')+f'>{t}</a>' for p,t in NAV)
    return f'''<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="BRIDGE Linqの操作ガイド・機能一覧・納品引継ぎ・維持費。初心者向けの図解と手順付き。"><meta name="color-scheme" content="light"><title>{E(title)} | BRIDGE Linq 利用ガイド</title><link rel="stylesheet" href="manual.css"><script src="manual.js" defer></script></head><body id="top"><a class="skip" href="#main">本文へ移動</a><header class="topbar"><div class="top-inner"><a href="index.html" class="brand">{MARK}<div>BRIDGE <span>Linq</span></div><small>利用ガイド・仕様書</small></a><nav class="tabs" aria-label="メインナビゲーション">{nav}</nav></div></header><main id="main" class="{'guide-layout' if wide else 'wrap'}">{body}</main><footer class="footer"><div>BRIDGE Linq · 利用ガイド / 2026.09.18<br>コード確認基準 {REV} · 本番反映や検収完了を保証する資料ではありません。</div><div><a href="features.html#sources">確認資料</a><a href="handover.html#costs">料金の根拠</a><a href="https://github.com/tmksh/hachi">ソースコード ↗</a></div></footer><a class="backtop" href="#top" aria-label="ページの先頭へ">↑</a></body></html>'''
def flow(items):
    return '<ol class="flow">'+''.join(f'<li><small>{i+1:02d} · {E(role)}</small><strong>{E(title)}</strong><span>{E(sub)}</span></li>' for i,(role,title,sub) in enumerate(items))+'</ol>'
def note(title,text,warn=False): return f'<div class="notice{" warn" if warn else ""}"><strong>{title}</strong>{text}</div>'
def table(headers,rows):return '<div class="table-wrap"><table><thead><tr>'+''.join(f'<th scope="col">{h}</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{c}</td>' for c in r)+'</tr>' for r in rows)+'</tbody></table></div>'
def figure(c):
    if not c.get('image'):return ''
    return f'<figure class="screen {"login" if c["id"]=="start" else ""}"><a href="{c["image"]}" target="_blank" rel="noopener" aria-label="{E(c["title"])}の画面例を拡大"><img src="{c["image"]}" alt="{E(c["title"])}の画面例" loading="lazy" width="1440" height="900"></a><figcaption>{E(c["caption"])} 画像を押すと拡大できます。</figcaption></figure>'
home=f'''<section class="hero"><div><p class="eyebrow">BRIDGE LINQ / USER GUIDE</p><h1>仕事の流れがわかる。<br>次の操作に、迷わない。</h1><p class="lede">問い合わせから、見積・契約・工事・支払いまで。<br>はじめて使う方のための、図で読む操作ガイドです。</p><div class="actions"><a class="btn primary" href="guide.html#start">はじめての操作へ <span>→</span></a><a class="btn" href="features.html">できることを見る</a></div></div>{ART}</section><div class="meta"><span>更新日　2026年9月18日</span><span>対象　営業・現場・総務・経営・管理者</span><span>スマートフォン・印刷対応</span></div>
<section class="section"><div class="section-head"><h2>目的から選ぶ</h2><p>使う方にも、引き継ぐ方にも。</p></div><div class="cards"><a class="card link" href="guide.html"><span class="number">01 / 使い方を知る</span><h3>画面を開いて、<br>順番に操作する。</h3><p>入口・入力内容・完了の目印を、業務ごとに説明します。</p><span class="arrow">操作ガイドへ →</span></a><a class="card link" href="features.html"><span class="number">02 / 仕様を確かめる</span><h3>できることと、<br>確認が必要なこと。</h3><p>機能の分類と元の確認表を検索。保留・対象外も見分けられます。</p><span class="arrow">機能一覧へ →</span></a><a class="card link" href="handover.html"><span class="number">03 / 運用を引き継ぐ</span><h3>何を受け取り、<br>いくらで運用するか。</h3><p>アカウント・データ・設定の引継ぎと、維持費の目安をまとめました。</p><span class="arrow">納品・維持費へ →</span></a></div></section>
<section class="section"><div class="section-head"><h2>まず、仕事の全体像</h2><p>1つの案件を、担当者同士でつなぎます。</p></div>{flow([('営業','問い合わせ・商談','顧客と次の対応'),('営業','見積・受注','内容と金額を確定'),('営業／総務','契約','書類と社内承認'),('現場','工事・発注','工程と原価を管理'),('現場／経理','検収・支払い','請求確認と帳票')])}<div class="read-this"><b>覚えておくこと</b><p>「保存」「承認」「送信」はそれぞれ違う操作です。<br>入力を保存したあとに、承認状態や相手への到着まで確認しましょう。</p></div></section>
<section class="section"><div class="section-head"><h2>自分の仕事から読み始める</h2></div><div class="cards two">'''
for title,text,link in [('営業の方','問い合わせ → 顧客・商談 → 見積 → 受注 → 契約','leads'),('現場担当の方','工程表 → 日報 → 追加変更 → 台帳 → 発注','construction'),('総務・経理の方','納品・請求確認 → 支払い確定 → 全銀・CSV','fulfillment'),('管理者・経営層の方','初期設定・権限 → BI・決算書 → 運用引継ぎ','settings')]:home+=f'<a class="card link" href="guide.html#{link}"><h3>{title}</h3><p>{text}</p><span class="arrow">手順を見る →</span></a>'
home+='</div></section><section class="section"><h2>操作を探す</h2><div class="searchbox"><label for="guide-search">何をしたいですか？</label><input id="guide-search" type="search" placeholder="例：見積、PDF、勤怠" autocomplete="off"></div><p id="guide-count" class="count" aria-live="polite"></p><div class="search-results">'
for c in chapters:home+=f'<a data-guide class="search-result" href="guide.html#{c["id"]}">{E(c["title"])}<small>{E(c["group"])} · {E(c["goal"])}</small></a>'
home+='</div><p id="guide-empty" class="empty" hidden>該当するガイドがありません。短い言葉に変えて検索してください。</p></section>'
