guide=toc+'<div class="guide-main"><div class="page-intro"><p class="eyebrow">HOW TO USE</p><h1>ひとつずつ、操作してみる。</h1><p class="lede">各章の「開く場所」から始め、番号の順に操作してください。最後の「完了の目印」で、保存や処理の結果を確認できます。</p><div class="actions"><button class="btn" data-print>操作ガイドを印刷・PDF保存</button><a class="btn" href="features.html">仕様・確認状況を見る →</a></div></div><details class="mobile-toc"><summary>目次を開く</summary><div class="detail-body">'+''.join(f'<p><a href="#{c["id"]}">{i+1:02d} {c["title"]}</a></p>' for i,c in enumerate(chapters))+'</div></details>'
for i,c in enumerate(chapters):
    guide+=f'<section class="chapter" id="{c["id"]}"><span class="chapter-number">{i+1:02d} / {c["group"]}</span><h2>{E(c["title"])}</h2><p class="role">主な利用者：{E(c["audience"])}</p><p class="lede">{E(c["goal"])}</p><div class="route">開く場所　{E(c["path"])}</div>'
    if c['id']=='pdf':guide+=mapping
    if c['id']=='won':guide+=flow([('営業','商談の受注確定','金額・見積を確認'),('営業','契約の確認','書類作成へ'),('現場','工事登録','住所・工期・担当')])
    if c['id']=='fulfillment':guide+=flow([('現場','納品検収','納品日・内容'),('業者／現場','請求書の提出','URLまたは紙'),('担当者','内容確認','PDFと金額'),('総務／経理','支払い確定','帳票の対象へ')])
    guide+=figure(c)+'<ol class="steps">'+''.join(f'<li><div><h3>{E(title)}</h3><p>{E(text)}</p></div></li>' for title,text in c['steps'])+'</ol>'
    if c.get('previewImage'):
        guide+=f'<figure class="screen"><a href="{c["previewImage"]}" target="_blank" rel="noopener" aria-label="PDF入力プレビューの画面例を拡大"><img src="{c["previewImage"]}" alt="サンプルの名称・会社名・金額が別々の欄に表示された入力プレビュー" loading="lazy" width="1200" height="630"></a><figcaption>入力プレビューの例。同じローカル検証画面で、名称・会社名・金額の対応を確認した状態です。PDF差し替え後の更新を検証した画像ではありません。</figcaption></figure>'
    guide+=f'<div class="done"><b>完了の目印</b>{E(c["done"])}</div><p class="tip">{E(c["tip"])}</p><details><summary>うまくいかないとき・確認すること</summary><p>{E(c["issue"])}</p></details><p class="small">原本の参照：{E(c["refs"])}</p>'
    if i<len(chapters)-1:guide+=f'<a class="next-link" href="#{chapters[i+1]["id"]}">次へ：{chapters[i+1]["title"]} →</a>'
